    leadAnswerBlock: '**Snug Protocol es una especificación abierta, con licencia MIT, para apps pequeñas creadas con IA que se ejecutan dentro de un programa host, toman prestado el modelo de IA del host mientras funcionan y guardan sus datos en un único archivo portátil propiedad del usuario.** Está en una fase temprana: la especificación va por la versión 1.0, pero la app para macOS está en la versión 0.1.3 y no se ha demostrado una adopción independiente.',
