        content: '**Snug بروتوكول، وليس نموذج ذكاء اصطناعي ولا تطبيقاً واحداً.** يصف كيف يتخاطب تطبيق ويب صغير وبرنامج مضيف ووكيل ذكاء اصطناعي، وأين تُحفظ بيانات التطبيق. ينطلق المشروع من فكرة أن التطبيق الذي يبنيه لك مساعد ذكاء اصطناعي يبقى عادةً مرتبطاً هو وبياناته بالمنصة التي أنشأته. الكود متاح في [مستودع snug على GitHub](https://github.com/snugprotocol/snug).',
